import React from 'react';
import { useQuery } from '@apollo/client';
import { GET_ALL_APPOINTMENTS } from '../../graphql/admin';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  Box,
  CircularProgress,
  Button,
  IconButton,
  Chip,
} from '@mui/material';
import { Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';

const AdminAppointmentList = ({ appointments = [], limit, onEdit, onDelete }) => {
  // Process appointments to ensure they have all required fields with defaults
  const processedAppointments = React.useMemo(() => {
    return (appointments || []).map(appt => ({
      id: appt.id || '',
      firstName: appt.firstName || appt.first_name || '',
      lastName: appt.lastName || appt.last_name || '',
      email: appt.email || '',
      phone: appt.phone || '',
      service: appt.service || '',
      appointmentDate: appt.appointmentDate || appt.appointment_date || new Date(),
      status: appt.status || 'pending',
      notes: appt.notes || '',
      documentSigned: appt.documentSigned || appt.document_signed || false,
      envelopeId: appt.envelopeId || appt.envelope_id || '',
      documentUrl: appt.documentUrl || appt.document_url || '',
      createdAt: appt.createdAt || appt.created_at || new Date(),
      updatedAt: appt.updatedAt || appt.updated_at || new Date()
    }));
  }, [appointments]);

  // Apply limit if provided
  const displayAppointments = limit 
    ? processedAppointments.slice(0, limit) 
    : processedAppointments;

  if (appointments.length === 0) {
    return (
      <Box p={4} textAlign="center">
        <Typography>No appointments found.</Typography>
      </Box>
    );
  }

  const getStatusColor = (status) => {
    switch (status?.toUpperCase()) {
      case 'PENDING':
        return 'warning';
      case 'CONFIRMED':
        return 'info';
      case 'COMPLETED':
        return 'success';
      case 'CANCELLED':
        return 'error';
      default:
        return 'default';
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleString();
  };

  return (
    <TableContainer component={Paper}>
      <Table>
        <TableHead>
          <TableRow>
            <TableCell>ID</TableCell>
            <TableCell>Name</TableCell>
            <TableCell>Service</TableCell>
            <TableCell>Date & Time</TableCell>
            <TableCell>Status</TableCell>
            <TableCell>Contact</TableCell>
            <TableCell>Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {displayAppointments.map((appointment) => (
            <TableRow key={appointment.id} hover>
              <TableCell>{appointment.id}</TableCell>
              <TableCell>
                {appointment.firstName} {appointment.lastName}
              </TableCell>
              <TableCell>{appointment.service}</TableCell>
              <TableCell>{formatDate(appointment.appointmentDate)}</TableCell>
              <TableCell>
                <Chip
                  label={appointment.status}
                  color={getStatusColor(appointment.status)}
                  size="small"
                />
              </TableCell>
              <TableCell>
                <Box>
                  <div>{appointment.email}</div>
                  <div>{appointment.phone}</div>
                </Box>
              </TableCell>
              <TableCell>
                <IconButton
                  onClick={() => onEdit && onEdit(appointment)}
                  size="small"
                  color="primary"
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  onClick={() => onDelete && onDelete(appointment)}
                  size="small"
                  color="error"
                >
                  <DeleteIcon />
                </IconButton>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default AdminAppointmentList;
